def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
    opp_rate = opp_c / float(n)

    recent10 = history[-10:]
    recent_opp_d = 0
    for i in range(len(recent10)):
        if recent10[i][1] == 'D':
            recent_opp_d += 1
    recent_opp_c = len(recent10) - recent_opp_d

    if n == 1:
        if last_opp == 'C':
            return 'D'
        return 'D'

    if n == 2:
        if history[1][0] == 'D':
            if last_opp == 'C':
                return 'C'
            if opp_rate > 0.0 and history[0][1] == 'C':
                return 'C'
            return 'D'
        return 'C'

    non = 0
    punish = 0
    start = max(0, n - 31)
    for i in range(start, n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                non += 1
            else:
                punish += 1

    fc = 0
    fd = 0
    for i in range(start, n - 1):
        if history[i][0] == 'C':
            fd += 1
            if history[i + 1][1] == 'C':
                fc += 1

    if fd == 0:
        forgiving = opp_rate >= 0.70
    elif fd < 4:
        forgiving = fc * 4 >= fd * 3
    else:
        forgiving = fc * 10 >= fd * 7

    hostile = opp_rate < 0.35
    if not hostile and n >= 12 and recent_opp_d >= 8:
        hostile = True
    if not hostile and n >= 20 and recent_opp_d >= 6 and opp_rate < 0.55:
        hostile = True

    if hostile:
        return 'D'

    exploitable = opp_rate >= 0.55 and non > 0 and non > punish and forgiving
    if not exploitable and opp_rate >= 0.75 and recent_opp_c >= 9 and non == 1 and punish == 0:
        exploitable = True

    if exploitable:
        if last_me == 'D' and last_opp == 'D':
            if opp_rate >= 0.5:
                return 'C'
            return 'D'
        if last_opp == 'D' and recent_opp_d <= 4:
            return 'C'
        return 'D'

    retaliatory_forgiving = opp_rate >= 0.45 and punish > 0 and non <= punish and forgiving
    if retaliatory_forgiving:
        if recent_opp_d >= 3:
            return 'D'
        if last_me == 'C' and recent_opp_d >= 2:
            return 'D'
        return 'C'

    if n >= 15 and n < 90 and opp_rate >= 0.85 and recent_opp_c >= 10 and punish == 0 and non == 0:
        if rng.random() < 0.08:
            return 'D'

    if n >= 97:
        if opp_rate >= 0.60 and forgiving and recent_opp_c >= 8:
            if non > punish:
                return 'D'
            return 'C'
        return 'C'

    if recent_opp_d >= 8:
        return 'D'
    if recent_opp_c >= 9:
        return 'C'
    if opp_rate >= 0.80:
        return 'C'
    if opp_rate <= 0.30:
        return 'D'

    if last_me == 'C' and last_opp == 'D':
        if forgiving and opp_rate >= 0.60 and recent_opp_d <= 3:
            return 'C'
        return 'D'

    if last_me == 'D' and last_opp == 'C':
        return 'C'

    if last_me == 'D' and last_opp == 'D':
        if opp_rate >= 0.50 and recent_opp_d <= 4:
            return 'C'
        return 'D'

    if n >= 20:
        last20 = history[-20:]
        d_after_d = 0
        for i in range(1, len(last20)):
            if last20[i - 1][1] == 'D' and last20[i][1] == 'D':
                d_after_d += 1
        if d_after_d >= 5:
            return 'D'

    if opp_rate > 0.50:
        return 'C'

    return 'C' if rng.random() < 0.55 else 'D'
